      }
      if (req.url === 'https://example.zendesk.com/api/v2/tickets/98765.json' && req.method === 'PUT') {
        expect(req.json).toEqual({
          ticket: {
            comment: {
              body: 'Issue created: https://github.com/octocat/repo/issues/456',
              public: true,
            },
          },
        })
        expect(req.headers.get('authorization')).toBe('Bearer zd-token')
        return jsonResponse({ ticket: { id: 98765, url: 'https://example.zendesk.com/api/v2/tickets/98765.json' } })
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      githubOwner: 'octocat',
      githubRepo: 'repo',
      githubToken: 'gh-token',
      zendeskSubdomain: 'example',
      zendeskToken: 'zd-token',
      fetch,
