  it('throws on GitHub non-2xx response', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.github.com/repos/octocat/repo/issues') {
        return jsonResponse({ message: 'Validation Failed' }, 422)
