    await expect(handle(payload, config)).rejects.toThrow('GitHub create issue failed: 422 Unprocessable Entity at https://api.github.com/repos/octocat/repo/issues')
    expect(calls).toHaveLength(1)
  })

  it('throws on Zendesk non-2xx response', async () => {
    const { fetch, calls } = fakeFetch((req) => {
