  "type": "zen:event-type:ticket.created",
  "account_id": 12345,
  "id": "abc-123-def",
  "time": "2025-08-24T12:34:56Z",
  "zendesk_event_version": "2022-06-20",
  "subject": "zen:ticket:98765",
  "detail": {
    "id": "98765",
    "subject": "Support needed",
    "description": "Customer reports login failure",
    "status": "open",
    "priority": "normal",
